// Compiles the local-recognition program (src/local/worker/) into a string module that main.js
// embeds (edition-dependent: math only in the private edition; git-ignored, generated by every
// build / test / typecheck). ONNX Runtime Web is embedded separately (build-embedded-ort.mjs).
import esbuild from 'esbuild';
import { editionOptions } from './edition.mjs';
import { writeFileSync, readFileSync, existsSync } from 'node:fs';

export async function buildWorker({ write = true } = {}) {
  const r = await esbuild.build({
    entryPoints: ['src/local/worker/entry.ts'],
    bundle: true,
    ...editionOptions(),
    format: 'iife',
    platform: 'browser',
    target: 'es2020',
    minify: true,
    write: false,
    legalComments: 'none',
    logLevel: 'warning',
  });
  const code = r.outputFiles[0].text;
  const out = `// Generated by scripts/build-worker.mjs from src/local/worker/ — do not edit.\nexport const WORKER_SRC = ${JSON.stringify(code)};\n`;
  const path = 'src/local/worker-src.generated.ts';
  const changed = !existsSync(path) || readFileSync(path, 'utf8') !== out;
  if (write && changed) writeFileSync(path, out);
  return { code, changed };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const { code, changed } = await buildWorker();
  console.log(`worker program ${(code.length / 1024).toFixed(1)} KB${changed ? ' (updated)' : ''}`);
}
